create function public.account_user_exists(p_user uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from auth.users where id=p_user) $$;
create function public.finish_account_deletion_job(p_user uuid,p_token uuid) returns boolean language plpgsql security definer set search_path='' as $$ begin delete from public.account_deletion_jobs where user_id=p_user and lease_token=p_token and lease_until>clock_timestamp() and not exists(select 1 from auth.users where id=p_user);return found;end $$;
revoke all on function public.account_user_exists(uuid),public.finish_account_deletion_job(uuid,uuid) from public;grant execute on function public.account_user_exists(uuid),public.finish_account_deletion_job(uuid,uuid) to service_role;
